        e.preventDefault();
        if (path && cur.getAttribute('aria-expanded') === 'true') { this.toggle(path, false); return; }
        const owner = cur.closest('.dk-tb-cat');
        const parent = owner && (path ? owner.parentElement.closest('.dk-tb-cat') : owner);
