  /** Inscrit une source de section dynamique, pour tous les langages ; rend une fonction qui la retire. */
  const source = (id, fn) => { SOURCES.set(id, fn); return () => { if (SOURCES.get(id) === fn) SOURCES.delete(id); }; };
