/*!
 * Zeugma · volets (DOM)
 *
 * SplitView dessine un PaneLayout (domino.workbench.js) : des groupes d'onglets côte à côte ou l'un sous
 * l'autre, séparés par des poignées qu'on tire (ou qu'on règle au clavier). Chaque onglet a un hôte DOM
 * gardé d'un rendu à l'autre : l'éditeur qu'il contient survit aux divisions, aux déplacements d'onglets.
 *
 *   const view = new Domino.SplitView(el, {
 *     layout: () => workbench.layout,
 *     tabInfo: (tabId) => ({ title, dirty, color, detail }),
 *     mount: (tabId, host) => …,                      // première fois qu'un onglet est montré
 *     onActivate, onClose, onFocusGroup, onContext, onMove, onSplitDrop, onResize, renderEmpty, onSplit,
 *   });
 *   view.render();          // après un changement de disposition
 *   view.renderTabs();      // après un changement de titre ou d'état « modifié »
 *
 * Gestes : clic (activer), clic du milieu (fermer), glisser un onglet (déplacer ; sur un bord : diviser),
 * clic droit ou Maj+F10 (menu de l'onglet). Poignée : glisser, flèches (2 %), Maj+flèches (10 %),
 * Début/Fin, double-clic (égaliser).
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const MIME = 'application/x-domino-tab';
  const SPLIT_ICON = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4"><rect x="2" y="2.5" width="12" height="11" rx="1.5"/><path d="M8 2.5v11"/></svg>';
  const MORE_ICON = '<svg viewBox="0 0 16 16" fill="currentColor"><circle cx="3.5" cy="8" r="1.3"/><circle cx="8" cy="8" r="1.3"/><circle cx="12.5" cy="8" r="1.3"/></svg>';

  class SplitView {
    constructor(el, o) {
      this.el = el;
      this.o = o;
      this.hosts = new Map();
      this.mounted = new Set();
      el.classList.add('pv-root');
      this._bind();
    }
    get layout() { return this.o.layout(); }
    /** L'hôte DOM d'un onglet (créé à la demande). */
    hostOf(tabId) {
      let h = this.hosts.get(tabId);
      if (!h) { h = document.createElement('div'); h.className = 'pv-host'; h.dataset.tab = tabId; h.setAttribute('role', 'tabpanel'); this.hosts.set(tabId, h); }
      return h;
    }
    /** Oublie l'hôte d'un onglet fermé. */
    drop(tabId) { const h = this.hosts.get(tabId); if (h) h.remove(); this.hosts.delete(tabId); this.mounted.delete(tabId); }

    render() {
      const L = this.layout;
      const build = (n) => {
        if (n.type === 'group') return this._group(n);
        const box = document.createElement('div');
        box.className = 'pv-split';
        box.dataset.dir = n.dir;
        box.dataset.split = n.id;
        n.children.forEach((c, i) => {
          if (i) {
            const s = document.createElement('div');
            s.className = 'pv-sash';
            s.setAttribute('role', 'separator');
            s.setAttribute('aria-orientation', n.dir === 'row' ? 'vertical' : 'horizontal');
            s.setAttribute('aria-label', n.dir === 'row' ? 'Redimensionner les volets (gauche, droite)' : 'Redimensionner les volets (haut, bas)');
            s.setAttribute('aria-valuemin', '15');
            s.setAttribute('aria-valuemax', '85');
            s.setAttribute('aria-valuenow', String(Math.round(n.sizes.slice(0, i).reduce((a, b) => a + b, 0) * 100)));
            s.tabIndex = 0;
            s.dataset.split = n.id;
            s.dataset.k = String(i);
            box.appendChild(s);
          }
          const cell = build(c);
          cell.style.flex = `${n.sizes[i]} 1 0px`;
          box.appendChild(cell);
        });
        return box;
      };
      // Les hôtes survivent : on les détache avant de reconstruire.
      for (const h of this.hosts.values()) if (h.parentNode) h.parentNode.removeChild(h);
      this.el.innerHTML = '';
      this.el.appendChild(build(L.root));
      this.el.classList.toggle('multi', L.groups().length > 1);
      this._mountActive();
    }
    _group(g) {
      const L = this.layout;
      const sec = document.createElement('section');
      sec.className = `pv-group${g.id === L.focused ? ' focused' : ''}`;
      sec.dataset.g = g.id;
      sec.setAttribute('aria-label', `Volet ${L.groups().indexOf(g) + 1}`);
      sec.innerHTML = `<div class="pv-bar"><div class="pv-tabs" role="tablist" aria-label="Onglets du volet ${L.groups().indexOf(g) + 1}"></div><div class="pv-acts"><button type="button" class="pv-act" data-act="split" title="Diviser à droite (${esc(D.Keys ? D.Keys.label('Mod+\\') : 'Ctrl+\\')})" aria-label="Diviser à droite">${SPLIT_ICON}</button><button type="button" class="pv-act" data-act="more" aria-haspopup="menu" aria-label="Actions du volet">${MORE_ICON}</button></div></div><div class="pv-body"></div><div class="pv-drop" hidden></div>`;
      this._tabs(sec, g);
      const body = sec.querySelector('.pv-body');
      if (!g.tabs.length && this.o.renderEmpty) this.o.renderEmpty(g.id, body);
      for (const t of g.tabs) { const h = this.hostOf(t); h.hidden = t !== g.active; body.appendChild(h); }
      return sec;
    }
    _tabs(sec, g) {
      const bar = sec.querySelector('.pv-tabs');
      bar.innerHTML = g.tabs.map((t) => {
        const i = this.o.tabInfo(t) || {};
        const on = t === g.active;
        return `<div class="pv-tab${on ? ' on' : ''}${i.dirty ? ' dirty' : ''}${i.pinned ? ' pinned' : ''}" role="tab" draggable="true" data-tab="${esc(t)}" aria-selected="${on}" tabindex="${on ? 0 : -1}" aria-label="${esc(i.title)}${i.dirty ? ', modifié' : ''}${i.detail ? `, ${esc(i.detail)}` : ''}" title="${esc(i.tooltip || i.title)}"><span class="pv-dot" style="--c:${esc(i.color || 'var(--ink-3)')}"></span><span class="pv-title">${esc(i.title)}</span>${i.detail ? `<small>${esc(i.detail)}</small>` : ''}<span class="pv-x" role="button" aria-label="Fermer ${esc(i.title)}" data-close="${esc(t)}" title="Fermer"><b aria-hidden="true">●</b><i aria-hidden="true">×</i></span></div>`;
      }).join('');
    }
    /** Met à jour les barres d'onglets (titres, états) sans toucher aux éditeurs. */
    renderTabs() {
      for (const g of this.layout.groups()) { const sec = this.el.querySelector(`.pv-group[data-g="${g.id}"]`); if (sec) this._tabs(sec, g); }
    }
    /** Montre l'onglet actif de chaque groupe (le monte la première fois), cache les autres. */
    _mountActive() {
      const L = this.layout;
      for (const g of L.groups()) {
        const sec = this.el.querySelector(`.pv-group[data-g="${g.id}"]`);
        if (!sec) continue;
        sec.classList.toggle('focused', g.id === L.focused);
        const body = sec.querySelector('.pv-body');
        for (const t of g.tabs) {
          const h = this.hostOf(t);
          if (h.parentNode !== body) body.appendChild(h);
          h.hidden = t !== g.active;
        }
        if (g.active && !this.mounted.has(g.active)) { this.mounted.add(g.active); this.o.mount(g.active, this.hostOf(g.active)); }
      }
      if (this.o.onShown) this.o.onShown();
    }
    /** Après activate/focus sans changement de structure. */
    refresh() { this.renderTabs(); this._mountActive(); }
    focusTab(tabId) { const el = this.el.querySelector(`.pv-tab[data-tab="${tabId}"]`); if (el) el.focus(); }

    // -------------------------------------------------------------------------
    // Gestes
    // -------------------------------------------------------------------------
    _bind() {
      const el = this.el;
      el.addEventListener('pointerdown', (e) => {
        const sec = e.target.closest('.pv-group');
        if (sec && this.o.onFocusGroup) this.o.onFocusGroup(sec.dataset.g);
        const s = e.target.closest('.pv-sash');
        if (s) this._sashDrag(s, e);
      });
      el.addEventListener('click', (e) => {
        const x = e.target.closest('[data-close]');
        if (x) { e.stopPropagation(); this.o.onClose(x.dataset.close); return; }
        const t = e.target.closest('.pv-tab');
        if (t) { this.o.onActivate(t.dataset.tab); return; }
        const a = e.target.closest('.pv-act');
        if (a) {
          const g = a.closest('.pv-group').dataset.g;
          if (a.dataset.act === 'split') this.o.onSplit(g);
          else { const r = a.getBoundingClientRect(); this.o.onGroupMenu(g, r.right, r.bottom + 2); }
        }
      });
      el.addEventListener('auxclick', (e) => { const t = e.target.closest('.pv-tab'); if (t && e.button === 1) { e.preventDefault(); this.o.onClose(t.dataset.tab); } });
      el.addEventListener('contextmenu', (e) => { const t = e.target.closest('.pv-tab'); if (t) { e.preventDefault(); this.o.onContext(t.dataset.tab, e.clientX, e.clientY); } });
      el.addEventListener('dblclick', (e) => {
        const s = e.target.closest('.pv-sash');
        if (s) { const sp = this.layout._node(s.dataset.split); this.o.onResize(s.dataset.split, sp.children.map(() => 1 / sp.children.length), true); return; }
        if (e.target.closest('.pv-tabs') && !e.target.closest('.pv-tab') && this.o.onNewTab) this.o.onNewTab(e.target.closest('.pv-group').dataset.g);
      });
      el.addEventListener('keydown', (e) => {
        const t = e.target.closest('.pv-tab');
        if (t) {
          const tabs = [...t.parentNode.querySelectorAll('.pv-tab')], i = tabs.indexOf(t);
          if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') { e.preventDefault(); const n = tabs[(i + (e.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length]; this.o.onActivate(n.dataset.tab, { keepFocus: true }); this.focusTab(n.dataset.tab); }
          else if (e.key === 'Home' || e.key === 'End') { e.preventDefault(); const n = tabs[e.key === 'Home' ? 0 : tabs.length - 1]; this.o.onActivate(n.dataset.tab, { keepFocus: true }); this.focusTab(n.dataset.tab); }
          else if (e.key === 'Delete') { e.preventDefault(); this.o.onClose(t.dataset.tab); }
          else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); this.o.onActivate(t.dataset.tab); }
          else if (e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10')) { e.preventDefault(); const r = t.getBoundingClientRect(); this.o.onContext(t.dataset.tab, r.left, r.bottom); }
          return;
        }
        const s = e.target.closest('.pv-sash');
        if (s) this._sashKey(s, e);
      });
      // Glisser un onglet : vers une autre barre (déplacer), vers le corps d'un volet (au centre : déplacer ; sur un bord : diviser).
      el.addEventListener('dragstart', (e) => {
        const t = e.target.closest('.pv-tab');
        if (!t) return;
        e.dataTransfer.setData(MIME, t.dataset.tab);
        e.dataTransfer.setData('text/plain', t.textContent.trim());
        e.dataTransfer.effectAllowed = 'move';
        this._dragTab = t.dataset.tab;
        el.classList.add('pv-dragging');
      });
      el.addEventListener('dragend', () => { this._dragTab = null; el.classList.remove('pv-dragging'); el.querySelectorAll('.pv-drop').forEach((d) => { d.hidden = true; }); el.querySelectorAll('.pv-tab.drop-before').forEach((d) => d.classList.remove('drop-before')); });
      el.addEventListener('dragover', (e) => {
        if (!this._dragTab) return;
        const sec = e.target.closest('.pv-group');
        if (!sec) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        el.querySelectorAll('.pv-tab.drop-before').forEach((d) => d.classList.remove('drop-before'));
        const drop = sec.querySelector('.pv-drop');
        if (e.target.closest('.pv-bar')) { drop.hidden = true; const t = e.target.closest('.pv-tab'); if (t) t.classList.add('drop-before'); return; }
        const zone = this._zone(sec, e);
        drop.hidden = false;
        drop.dataset.zone = zone;
        el.querySelectorAll('.pv-drop').forEach((d) => { if (d !== drop) d.hidden = true; });
      });
      el.addEventListener('drop', (e) => {
        const tab = this._dragTab || e.dataTransfer.getData(MIME);
        const sec = e.target.closest('.pv-group');
        if (!tab || !sec) return;
        e.preventDefault();
        const g = sec.dataset.g;
        if (e.target.closest('.pv-bar')) {
          const t = e.target.closest('.pv-tab');
          const tabs = [...sec.querySelectorAll('.pv-tab')].map((x) => x.dataset.tab);
          this.o.onMove(tab, g, t ? tabs.indexOf(t.dataset.tab) : tabs.length);
        } else {
          const zone = this._zone(sec, e);
          if (zone === 'center') this.o.onMove(tab, g);
          else this.o.onSplitDrop(tab, g, zone);
        }
        el.dispatchEvent(new Event('dragend'));
      });
    }
    _zone(sec, e) {
      const r = sec.querySelector('.pv-body').getBoundingClientRect();
      const fx = (e.clientX - r.left) / r.width, fy = (e.clientY - r.top) / r.height;
      if (fx < 0.25) return 'left';
      if (fx > 0.75) return 'right';
      if (fy < 0.25) return 'up';
      if (fy > 0.75) return 'down';
      return 'center';
    }
    _sizesFrom(box) { return [...box.children].filter((c) => !c.classList.contains('pv-sash')).map((c) => parseFloat(c.style.flex) || 1); }
    _apply(box, sizes) { [...box.children].filter((c) => !c.classList.contains('pv-sash')).forEach((c, i) => { c.style.flex = `${sizes[i]} 1 0px`; }); }
    _sashDrag(s, e) {
      e.preventDefault();
      const box = s.parentNode, row = box.dataset.dir === 'row';
      const k = +s.dataset.k;
      const cells = [...box.children].filter((c) => !c.classList.contains('pv-sash'));
      const a = cells[k - 1], b = cells[k];
      const ra = a.getBoundingClientRect(), rb = b.getBoundingClientRect();
      const start = row ? e.clientX : e.clientY;
      const total = row ? ra.width + rb.width : ra.height + rb.height;
      const sizes = this._sizesFrom(box), pair = sizes[k - 1] + sizes[k];
      const min = 0.15 * sizes.reduce((x, y) => x + y, 0);
      s.setPointerCapture(e.pointerId);
      s.classList.add('on');
      document.body.classList.add(row ? 'pv-resizing-x' : 'pv-resizing-y');
      let next = sizes;
      const move = (ev) => {
        const d = ((row ? ev.clientX : ev.clientY) - start) / total * pair;
        const sa = Math.max(min, Math.min(pair - min, sizes[k - 1] + d));
        next = sizes.slice(); next[k - 1] = sa; next[k] = pair - sa;
        this._apply(box, next);
        s.setAttribute('aria-valuenow', String(Math.round(next.slice(0, k).reduce((x, y) => x + y, 0) / next.reduce((x, y) => x + y, 0) * 100)));
      };
      const up = () => {
        s.removeEventListener('pointermove', move); s.removeEventListener('pointerup', up); s.removeEventListener('pointercancel', up);
        s.classList.remove('on');
        document.body.classList.remove('pv-resizing-x', 'pv-resizing-y');
        const t = next.reduce((x, y) => x + y, 0);
        this.o.onResize(box.dataset.split, next.map((x) => x / t), false);
      };
      s.addEventListener('pointermove', move); s.addEventListener('pointerup', up); s.addEventListener('pointercancel', up);
    }
    _sashKey(s, e) {
      const box = s.parentNode, row = box.dataset.dir === 'row', k = +s.dataset.k;
      const keys = row ? { dec: 'ArrowLeft', inc: 'ArrowRight' } : { dec: 'ArrowUp', inc: 'ArrowDown' };
      let sizes = this._sizesFrom(box);
      const t = sizes.reduce((x, y) => x + y, 0);
      sizes = sizes.map((x) => x / t);
      const pair = sizes[k - 1] + sizes[k];
      const step = e.shiftKey ? 0.1 : 0.02;
      let sa = sizes[k - 1];
      if (e.key === keys.dec) sa -= step;
      else if (e.key === keys.inc) sa += step;
      else if (e.key === 'Home') sa = 0;
      else if (e.key === 'End') sa = pair;
      else return;
      e.preventDefault();
      sa = Math.max(0.15, Math.min(pair - 0.15, sa));
      sizes[k - 1] = sa; sizes[k] = pair - sa;
      this._apply(box, sizes);
      s.setAttribute('aria-valuenow', String(Math.round(sizes.slice(0, k).reduce((x, y) => x + y, 0) * 100)));
      this.o.onResize(box.dataset.split, sizes, false);
    }
  }

  D.SplitView = SplitView;
})(typeof globalThis !== 'undefined' ? globalThis : window);
