/*!
 * Zeugma · DominoPopup
 * « Configurer » une pierre : une grande pierre s'agrandit à partir d'elle. À gauche la table, avec la pierre
 * en grand et ses voisines des quatre côtés (la précédente à gauche, les suites à droite, les adjacentes
 * hautes au-dessus de l'entrée, les basses sous la sortie) ; à droite la fiche. Entre les deux, la ligne de
 * partage et le pivot en laiton, comme sur un vrai domino.
 * Cliquer une voisine la prend en main ; un point de la grande pierre montre ce qui le relie.
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const K = () => root.DominoKit;
  const U = () => D.layoutUtil;
  const esc = (s) => K().esc(s);
  const reduced = () => typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;
  const DIRS = [['N', '↑ haut'], ['W', '← gauche'], ['E', '→ droite'], ['S', '↓ bas'], ['straight', '⇥ tout droit'], ['', 'auto']];

  class Popup {
    constructor(ed) {
      this.ed = ed;
      this.ws = ed.ws;
      this.id = null;
      this.trail = [];
      this.tab = 'fiche';
      this.dtab = 'warn';
      this.pip = null;
      const el = (this.layer = document.createElement('div'));
      el.className = 'dk-pp-layer';
      el.hidden = true;
      el.innerHTML = `<div class="dk-pp-scrim" data-act="close"></div>
        <div class="dk-pp" role="dialog" aria-modal="true" aria-label="Configurer la pierre">
          <div class="dk-pp-inner">
            <div class="dk-pp-table">
              <svg class="dk-pp-svg" role="group" aria-label="La pierre et ses voisines"></svg>
              <div class="dk-pp-top"><nav class="dk-pp-crumbs" aria-label="Parcours"></nav></div>
              <p class="dk-pp-legend"><b>Cliquer une voisine</b> pour la prendre en main · <b>un point</b> pour voir ce qui le relie · flèches : voisines · Échap : fermer</p>
            </div>
            <span class="dk-pp-pin" aria-hidden="true"></span>
            <aside class="dk-pp-side"></aside>
          </div>
        </div>`;
      ed.root.appendChild(el);
      this.box = el.querySelector('.dk-pp');
      this.svg = el.querySelector('.dk-pp-svg');
      this.side = el.querySelector('.dk-pp-side');
      el.addEventListener('click', (e) => this._click(e));
      el.addEventListener('keydown', (e) => this._key(e));
      this._off = this.ws.on('change', () => { if (this.id) { if (!this.ws.get(this.id)) this.close(true); else this.render(); } });
    }

    get isOpen() { return !!this.id; }

    /** Ouvre la popup sur une pierre : elle grandit à partir de la pierre posée sur la table. */
    open(id) {
      const n = this.ws.get(id);
      if (!n) return;
      this.ed.hideMenu(); this.ed.hideQuick();
      this.id = id; this.trail = [id]; this.pip = null; this.tab = 'fiche';
      this.layer.hidden = false;
      this.render();
      this._returnFocus = document.activeElement;
      const from = this._tileRect(id);
      const box = this.box;
      if (from && !reduced()) {
        const to = box.getBoundingClientRect();
        box.style.transition = 'none';
        box.style.transform = `translate(${from.left - to.left}px, ${from.top - to.top}px) scale(${from.width / to.width}, ${from.height / to.height})`;
        box.style.opacity = '.6';
        void box.getBoundingClientRect();
        box.style.transition = '';
      }
      requestAnimationFrame(() => { this.layer.classList.add('in'); box.style.transform = ''; box.style.opacity = ''; });
      setTimeout(() => { const f = this.side.querySelector('.dk-pp-name'); if (f) f.focus({ preventScroll: true }); }, 60);
      this.ws.emit('popup', { type: 'popup', id, open: true, at: Date.now() });
    }
    close(instant) {
      if (!this.id) return;
      const id = this.id;
      this.id = null;
      const to = this._tileRect(id), box = this.box;
      this.layer.classList.remove('in');
      if (!instant && to && !reduced()) {
        const r = box.getBoundingClientRect();
        box.style.transform = `translate(${to.left - r.left}px, ${to.top - r.top}px) scale(${to.width / r.width}, ${to.height / r.height})`;
        box.style.opacity = '0';
        setTimeout(() => { if (!this.id) { this.layer.hidden = true; box.style.transform = ''; box.style.opacity = ''; } }, 320);
      } else this.layer.hidden = true;
      if (this.ws.get(id)) this.ed.select(id, { reveal: false });
      this.ws.emit('popup', { type: 'popup', id, open: false, at: Date.now() });
    }
    /** Prend en main une voisine. */
    focus(id) {
      if (!this.ws.get(id) || id === this.id) return;
      const i = this.trail.indexOf(id);
      if (i >= 0) this.trail = this.trail.slice(0, i + 1); else this.trail.push(id);
      this.id = id; this.pip = null;
      this.svg.classList.remove('entering');
      void this.svg.getBoundingClientRect();
      this.svg.classList.add('entering');
      this.render();
      this.ed.select(id, { focus: false, reveal: true });
    }
    _tileRect(id) {
      const el = this.ed.world.querySelector(`.dk-node[data-id="${id}"] .t-face`);
      const r = el && el.getBoundingClientRect();
      return r && r.width ? r : null;
    }

    render() {
      const n = this.ws.get(this.id);
      if (!n) return;
      this._stage(n);
      this._side(n);
      this.layer.querySelector('.dk-pp-crumbs').innerHTML = `<span>Parcours</span>${this.trail.filter((id) => this.ws.get(id)).map((id) => `<button data-act="crumb" data-id="${id}" aria-current="${id === this.id}">${esc(this.ws.titleOf(this.ws.get(id)))}</button>`).join('<span aria-hidden="true">›</span>')}`;
    }

    // -------------------------------------------------------------------------
    // La table : la pierre en grand et ses voisines des quatre côtés
    // -------------------------------------------------------------------------
    _stage(n) {
      const ws = this.ws, Kit = K(), Ut = U(), T = 92, t = 46, gap = 64;
      const lay = new D.Layout(ws, { T, headerSize: 15, labels: true, maxDepth: 3 });
      const u = lay.unit(n, 'E');
      const W = 2 * T, D0 = Kit.depth(T);
      const els = [], boxes = [{ x: u.ext.x1, y: u.ext.y1, w: u.ext.x2 - u.ext.x1, h: u.ext.y2 - u.ext.y1 }];
      const tile = (node, x, y, H, o = {}) => {
        const s = Kit.tileSVG(Ut.kitData(ws, node, { asTop: o.asTop }), { H, orient: o.orient || 'h', flip: false, header: o.header !== false, headerSize: o.headerSize || 11, splitHead: true, mini: H < 40, pipHit: !!o.pipHit, title: false, badge: o.badge, skin: this.ed.o.skin, containerColor: this.ed.o.containerColor });
        const cls = o.cls || 'nb';
        els.push(`<g class="dk-pp-t ${cls}" ${cls === 'nb' ? `data-focus="${node.id}" tabindex="0" role="button" aria-label="Prendre en main « ${esc(ws.titleOf(node))} »"` : ''} transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><g filter="url(#dk-shadow)">${s.svg}</g>${o.headerDx ? `<g transform="translate(${o.headerDx} 0)">${s.headSvg}</g>` : s.headSvg}</g>`);
        return s;
      };
      const knob = (x, y, v) => els.push(`<rect class="dk-pp-knob" x="${(v ? x - 9 : x - 3).toFixed(1)}" y="${(v ? y - 3 : y - 9).toFixed(1)}" width="${v ? 18 : 6}" height="${v ? 6 : 18}" rx="3"/>`);
      const slot = (x, y, w, h, label, act, data = '') => { els.push(`<g class="dk-pp-ph" data-act="${act}" ${data} tabindex="0" role="button"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${Math.min(w, h) * 0.14}"/><text x="${x + w / 2}" y="${y + h / 2 + 4}" text-anchor="middle">${esc(label)}</text></g>`); boxes.push({ x, y, w, h }); };
      const seal = (x, y, text, anchor) => { els.push(`<line class="dk-pp-seal-bar" x1="${x}" y1="${y - 26}" x2="${x}" y2="${y + 26}"/><text class="dk-pp-seal" x="${anchor === 'end' ? x - 12 : x + 12}" y="${y + 4}" text-anchor="${anchor}">${esc(text)}</text>`); boxes.push({ x: anchor === 'end' ? x - 220 : x, y: y - 30, w: 220, h: 60 }); };
      const { left, right } = ws.pipsOf(n), def = n.def, cy = T / 2;
      // Adjacentes (mêmes règles que sur la table)
      for (const p of u.parts) {
        const c = ws.get(p.id);
        const pk = Ut.kitOrient(p.angle);
        tile(c, p.rect.x, p.rect.y, p.T, { orient: pk.orient, header: false, asTop: p.fam === 'top' });
        if (p.label) els.push(`<text class="dk-pp-lab" x="${p.label.x}" y="${p.label.y}" font-size="${p.label.f + 1}" text-anchor="${p.label.anchor}"${p.label.rot ? ` transform="rotate(${p.label.rot} ${p.label.x} ${p.label.y})"` : ''}>${esc(p.label.text)}</text>`);
      }
      // La pierre. Si l'emplacement « + haute » est libre, l'entête passe au-dessus de l'autre moitié, comme sur la table.
      const diags = ws.diagnostics.get(n.id) || [];
      const topSlot = def.top.open && left.length && !n.top.length;
      const hw = Kit.layoutTile(Ut.kitData(ws, n), { H: T, header: true, headerSize: 15 }).headW;
      const hdx = topSlot ? Math.max(T / 2 + t / 2 + 8, 0.75 * W - hw / 2) + hw / 2 - W / 2 : u.headerDx;
      tile(n, 0, 0, T, { pipHit: true, cls: 'me', headerSize: 15, headerDx: hdx, badge: diags.some((d) => d.level === 'error') ? 'error' : diags.length ? 'warn' : null });
      // Emplacements libres en haut et en bas
      if (topSlot) slot(T / 2 - t / 2 + 2, -t * 2 + 4, t - 4, t * 2 - 10, '+', 'add', 'data-via="top" aria-label="Ajouter une adjacente haute"');
      if (def.bottom.open && right.length && !n.bottom.length) slot(1.5 * T - t / 2 + 2, T + D0 + 6, t - 4, t * 2 - 10, '+', 'add', 'data-via="bottom" aria-label="Ajouter une adjacente basse"');
      // À gauche : la précédente, le parent d'une adjacente, ou la face scellée
      const p = ws.parentOf(n);
      if (p && n.parent.via === 'next') {
        const x = -gap - 2 * t;
        tile(p, x, cy - t / 2, t);
        knob(-gap / 2, cy, false);
        els.push(`<path class="dk-pp-wire" d="M${x + 2 * t} ${cy} H0"/>`);
        boxes.push({ x: x - 10, y: cy - t / 2 - 22, w: 2 * t + 20, h: t + 30 });
      } else if (p) {
        // Adjacente : son parent est de l'autre côté de la colonne.
        const up = n.parent.via === 'bottom';
        const y = up ? Math.min(u.ext.y1, -10) - gap - t : Math.max(u.ext.y2, T + D0) + gap;
        const px = T - t;
        tile(p, px, y, t);
        knob(T, up ? y + t + gap / 2 : y - gap / 2, true);
        els.push(`<text class="dk-pp-cap" x="${T}" y="${up ? y - 14 : y + t + Kit.depth(t) + 26}" text-anchor="middle">${up ? 'consomme la sortie de' : 'alimente'} « ${esc(ws.titleOf(p))} »</text>`);
        boxes.push({ x: px - 60, y: up ? y - 34 : y, w: 2 * t + 120, h: t + 40 });
      }
      const chain = def.chain;
      // Les fils : leurs sources à gauche (sous la précédente), leurs cibles à droite (sous les suites).
      const wIn = ws.wiresInto(n.id).filter((w) => ws.get(w.from.id)), wOut = ws.wiresFrom(n.id).filter((w) => ws.get(w.to.id));
      const pipAt = (side, i) => { const count = side === 'in' ? left.length : right.length; const q = Kit.pipXY(count, side, T, 'h', false)[Math.min(i, Math.max(0, count - 1))]; return q || { x: side === 'in' ? 0 : W, y: cy }; };
      const wireTo = (a, b, ca, cb, dashed) => {
        const gid = `pp-g-${els.length}`, k = Math.max(30, Math.abs(b.x - a.x) * 0.45);
        els.push(`<defs><linearGradient id="${gid}" gradientUnits="userSpaceOnUse" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"><stop offset="0" stop-color="${ca}"/><stop offset="1" stop-color="${cb}"/></linearGradient></defs><path class="dk-pp-fil${dashed ? ' async' : ''}" d="M${a.x} ${a.y} C${a.x + a.dx * k} ${a.y}, ${b.x - b.dx * k} ${b.y}, ${b.x} ${b.y}" stroke="url(#${gid})"/>`);
      };
      const col = (node, side, i) => this.ed._pipColor(node, side, i);
      let leftRow = p && n.parent.via === 'next' ? 1 : 0;
      wIn.forEach((w) => {
        const src = ws.get(w.from.id), info = this.ed.wireInfo(w);
        const x = -gap - 2 * t, y = cy - t / 2 + leftRow++ * (t + 46);
        tile(src, x, y, t);
        const q = pipAt('in', w.to.pip);
        wireTo({ x: x + 2 * t, y: y + t / 2, dx: 1 }, { x: q.x, y: q.y, dx: 1 }, col(src, 'out', w.from.pip), col(n, 'in', w.to.pip), info.async);
        els.push(`<text class="dk-pp-cap" x="${x}" y="${y + t + Kit.depth(t) + 15}">⌇ ${esc(info.outN)} → ${esc(info.inN)}${info.kind !== 'data' ? ` · ${w.blocking === false ? 'non bloquant' : 'bloquant'}` : ''}</text>`);
        boxes.push({ x: x - 10, y: y - 22, w: 2 * t + 60, h: t + 44 });
      });
      if (!chain) { /* libre : ni avant ni suite, seulement des fils */ }
      else if (!left.length) seal(-14, cy, 'Face gauche à zéro : rien ne la précède', 'end');
      else if (!p) slot(-gap - 2 * t, cy - t / 2 + (wIn.length ? -(t + 46) : 0), 2 * t, t, 'Avant…', 'add', 'data-via="prev" aria-label="Ajouter une pierre avant"');
      // À droite : les suites, une par sortie occupée, puis un emplacement libre
      const nexts = n.next.map((l, i) => (l && ws.get(l.id) ? { i, node: ws.get(l.id), link: l } : null)).filter(Boolean);
      const free = right.findIndex((_, i) => !n.next[i]);
      const rows = (chain ? nexts.length + (free >= 0 ? 1 : 0) : 0) + wOut.length;
      const pitch = t + 46;
      nexts.forEach((c, k) => {
        const y = cy - t / 2 + (k - (rows - 1) / 2) * pitch, x = W + gap;
        const yc = y + t / 2;
        els.push(`<path class="dk-pp-wire" d="M${W} ${cy} H${W + gap / 2} V${yc} H${x}"/>`);
        knob(W + gap / 2, yc, false);
        tile(c.node, x, y, t);
        const q = right[c.i];
        els.push(`<text class="dk-pp-cap" x="${x}" y="${y + t + Kit.depth(t) + 15}">${esc(q ? q.name : `sortie ${c.i + 1}`)}${c.link.label ? ` · ${esc(c.link.label)}` : ''}</text>`);
        boxes.push({ x, y: y - 22, w: 2 * t + 40, h: t + 44 });
      });
      if (!chain) { /* libre */ }
      else if (!right.length) seal(W + 14, cy, 'Face droite à zéro : rien ne la suit', 'start');
      else if (free >= 0) {
        const y = cy - t / 2 + (nexts.length - (rows - 1) / 2) * pitch;
        slot(W + gap, y, 2 * t, t, nexts.length ? `Sortie « ${right[free].name} »…` : 'Suite…', 'add', `data-via="next" data-pip="${free}" aria-label="Ajouter une suite"`);
      }
      const r0 = chain ? nexts.length + (free >= 0 ? 1 : 0) : 0;
      wOut.forEach((w, k) => {
        const dst = ws.get(w.to.id), info = this.ed.wireInfo(w);
        const y = cy - t / 2 + (r0 + k - (rows - 1) / 2) * pitch, x = W + gap + 30;
        tile(dst, x, y, t);
        const q = pipAt('out', w.from.pip);
        wireTo({ x: q.x, y: q.y, dx: 1 }, { x, y: y + t / 2, dx: 1 }, col(n, 'out', w.from.pip), col(dst, 'in', w.to.pip), info.async);
        els.push(`<text class="dk-pp-cap" x="${x}" y="${y + t + Kit.depth(t) + 15}">⌇ ${esc(info.outN)} → ${esc(info.inN)}${info.kind !== 'data' ? ` · ${w.blocking === false ? 'non bloquant' : 'bloquant'}` : ''}</text>`);
        boxes.push({ x, y: y - 22, w: 2 * t + 80, h: t + 44 });
      });
      const b = Ut.boundsOf(boxes), pad = 34;
      this.svg.setAttribute('viewBox', `${(b.x - pad).toFixed(1)} ${(b.y - pad).toFixed(1)} ${(b.w + pad * 2).toFixed(1)} ${(b.h + pad * 2).toFixed(1)}`);
      this.svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
      this.svg.innerHTML = els.join('');
      if (this.pip) {
        const h = this.svg.querySelector(`.me .t-pip-hit[data-side="${this.pip.side}"][data-i="${this.pip.i}"]`);
        if (h) h.classList.add('on');
      }
    }

    // -------------------------------------------------------------------------
    // La fiche
    // -------------------------------------------------------------------------
    _side(n) {
      const ws = this.ws, def = n.def, T = ws.types;
      const { left, right } = ws.pipsOf(n), sem = ws.semanticsOf(n);
      const diags = ws.diagnostics.get(n.id) || [];
      const warns = diags.filter((d) => d.level === 'warn'), errs = diags.filter((d) => d.level === 'error');
      const logs = ws.logs.filter((l) => l.dominoId === n.id);
      const p = ws.parentOf(n);
      const tabs = [['fiche', 'Fiche'], ['points', 'Points'], ['links', 'Connexions'], ['diag', `Diagnostic <span class="n${errs.length ? ' e' : warns.length ? ' w' : ''}">${errs.length + warns.length || logs.length}</span>`]];
      const link = (id) => `<button class="dk-link" data-act="go" data-id="${id}">${esc(ws.titleOf(ws.get(id)))}</button>`;
      let body;
      if (this.tab === 'fiche') {
        const r = this.ed.L && this.ed.L.R[n.id];
        body = `${def.description || def.help ? `<section class="dk-pp-card"><p>${esc(def.description || def.help)}</p></section>` : ''}
          <section class="dk-pp-card"><h3>Signification des faces <small>${left.length} | ${right.length}</small></h3><p><b>${esc(sem.label)}.</b> ${esc(sem.text)}</p></section>
          ${Object.keys(def.fields).some((k) => !def.fields[k].hidden) ? `<section class="dk-pp-card"><h3>Champs <small>{ } : liaison au contexte</small></h3>${D.ui.fieldsHTML(ws, n)}</section>` : ''}
          <section class="dk-pp-card"><h3>Note, état, provenance${def.represents ? ` <small>représente : ${esc(def.represents)}</small>` : ''}</h3>${D.ui.aboutHTML(ws, n)}</section>
          ${def.meaning ? `<section class="dk-pp-card"><h3>Ce que comptent les faces</h3>${def.meaning.left ? `<p><b>Gauche :</b> ${esc(def.meaning.left)}.</p>` : ''}${def.meaning.right ? `<p><b>Droite :</b> ${esc(def.meaning.right)}.</p>` : ''}</section>` : ''}
          ${r && right.length && def.chain ? `<section class="dk-pp-card"><h3>Sens de la suite</h3><div class="dk-chips">${DIRS.map(([d, l]) => `<button class="dk-chip${(n.turn || '') === d ? ' on' : ''}" data-act="turn" data-d="${d}" ${d === D.OPP[r.hd] ? 'disabled title="Demi-tour impossible"' : ''}>${l}</button>`).join('')}</div></section>` : ''}`;
      } else if (this.tab === 'points') {
        const fed = ws.feedersOf(n);
        const row = (q, i, side) => {
          const on = this.pip && this.pip.side === side && this.pip.i === i;
          let rel;
          if (side === 'in') rel = fed[i] ? `${fed[i].via === 'top' ? '↑' : fed[i].via === 'wire' ? '⌇' : '←'} ${link(fed[i].node.id)}` : `<span class="miss">non alimentée</span> <button class="dk-link" data-act="add" data-via="top">alimenter…</button>`;
          else {
            const users = [];
            if (n.next[i] && ws.get(n.next[i].id)) users.push(`→ ${link(n.next[i].id)}`);
            n.bottom.filter((a) => a.pip === i).forEach((a) => users.push(`↓ ${link(a.id)}`));
            ws.wiresFrom(n.id, i).forEach((w) => users.push(`⌇ ${link(w.to.id)}`));
            rel = users.join(', ') || `<span class="miss">libre</span>${def.chain ? ` <button class="dk-link" data-act="add" data-via="next" data-pip="${i}">suite…</button>` : ''}`;
          }
          return `<li class="${on ? 'on' : ''}" data-act="pip" data-side="${side}" data-i="${i}"><span class="ix">${side === 'in' ? 'E' : 'S'}${i + 1}</span><i style="--c:${q.color || T.color(q.type)}"></i><span class="nm"><b>${esc(q.name)}</b><small>${esc(T.label(q.type))}${q.accepts ? ` · accepte ${esc(q.accepts.join(', '))}` : ''}</small></span><span class="rel">${rel}</span></li>`;
        };
        body = `<section class="dk-pp-card"><h3>Face gauche <small>entrées · ${left.length}</small></h3>${left.length ? `<ul class="dk-pp-ports">${left.map((q, i) => row(q, i, 'in')).join('')}</ul>` : '<p class="muted">Zéro : rien ne la précède. Elle commence une chaîne ou alimente une pierre.</p>'}</section>
          <section class="dk-pp-card"><h3>Face droite <small>sorties · ${right.length}</small></h3>${right.length ? `<ul class="dk-pp-ports">${right.map((q, i) => row(q, i, 'out')).join('')}</ul>` : '<p class="muted">Zéro : rien ne la suit. Elle termine une chaîne ou consomme une sortie.</p>'}</section>
          <p class="muted">La couleur d’un point est son type : deux points se relient quand leurs types vont ensemble.</p>`;
      } else if (this.tab === 'links') {
        const lk = p && n.parent.via === 'next' ? p.next[n.parent.pip] : null;
        body = `<section class="dk-pp-card"><h3>Précédente</h3>${p ? `<p>${n.parent.via === 'next' ? '← ' : n.parent.via === 'top' ? 'alimente ' : 'consomme la sortie de '}${link(p.id)}</p>` : `<p class="muted">${left.length ? 'Aucune : c’est une tête de chaîne.' : 'Face gauche à zéro.'}</p>`}
            ${lk ? `<div class="dk-field"><label>libellé</label><input class="dk-txt" data-link="label" value="${esc(lk.label || '')}" placeholder="ex. ok, refusé"><span></span></div>
              <div class="dk-field"><label>condition</label><input class="dk-txt" data-link="cond" value="${esc(lk.cond || '')}" placeholder="ex. value.total > 0"><span></span></div>
              <div class="dk-field"><label>active</label><label class="dk-chk"><input type="checkbox" data-link="enabled" ${lk.enabled !== false ? 'checked' : ''}> ${lk.enabled !== false ? 'oui' : 'non'}</label><span></span></div>` : ''}</section>
          <section class="dk-pp-card"><h3>Suites <small>${n.next.filter(Boolean).length} / ${right.length}</small></h3>${right.length ? `<ul class="dk-pp-list">${right.map((q, i) => `<li><span>${esc(q.name)}</span>${n.next[i] && ws.get(n.next[i].id) ? link(n.next[i].id) : `<button class="dk-btn" data-act="add" data-via="next" data-pip="${i}">Ajouter…</button>`}</li>`).join('')}</ul>` : '<p class="muted">Face droite à zéro.</p>'}</section>
          <section class="dk-pp-card"><h3>Adjacentes <small>haute ${n.top.length} · basse ${n.bottom.length}</small></h3><ul class="dk-pp-list">${n.top.map((a) => `<li><span>↑ ${esc((left[a.pip] || {}).name || '')}</span>${link(a.id)}</li>`).join('')}${n.bottom.map((a) => `<li><span>↓ ${esc((right[a.pip] || {}).name || '')}</span>${link(a.id)}</li>`).join('')}</ul>
            <div class="dk-chips">${def.top.open && left.length ? '<button class="dk-btn" data-act="add" data-via="top">+ haute</button>' : ''}${def.bottom.open && right.length ? '<button class="dk-btn" data-act="add" data-via="bottom">+ basse</button>' : ''}</div></section>
          <section class="dk-pp-card"><h3>Fils <small>${ws.wiresOf(n.id).length}</small></h3>${ws.wiresOf(n.id).length ? `<ul class="dk-pp-list">${ws.wiresOf(n.id).map((w) => { const info = this.ed.wireInfo(w); const other = w.from.id === n.id ? w.to.id : w.from.id; return `<li><span>${w.from.id === n.id ? `${esc(info.outN)} →` : `← ${esc(info.inN)}`}</span><span>${link(other)}${info.kind !== 'data' ? ` <span class="dk-chips" style="display:inline-flex"><button class="dk-chip${w.blocking !== false ? ' on' : ''}" data-act="wblock" data-w="${w.id}" data-v="1">bloquant</button><button class="dk-chip${w.blocking === false ? ' on' : ''}" data-act="wblock" data-w="${w.id}" data-v="0">non bloquant</button></span>` : ''} <button class="dk-link" data-act="wdel" data-w="${w.id}" style="color:var(--err)">retirer</button></span></li>`; }).join('')}</ul>` : '<p class="muted">Aucun fil. Tirez un fil depuis un point de la pierre, sur la table.</p>'}</section>`;
      } else {
        const sub = this.dtab;
        const items = sub === 'warn' ? warns.map((d) => `<li class="w">${esc(d.message)}</li>`) : sub === 'error' ? errs.map((d) => `<li class="e">${esc(d.message)}</li>`) : logs.slice(-60).reverse().map((l) => `<li class="l">${new Date(l.at).toLocaleTimeString('fr-FR')} · ${esc(l.message)}</li>`);
        const lr = n.state.lastRun;
        body = `<div class="dk-pp-sub" role="tablist">${[['warn', `Avertissements ${warns.length}`], ['error', `Erreurs ${errs.length}`], ['log', `Journal ${logs.length}`]].map(([k, l]) => `<button role="tab" data-act="dtab" data-t="${k}" aria-selected="${sub === k}">${l}</button>`).join('')}</div>
          <ul class="dk-pp-dlist">${items.join('') || `<li class="empty">${sub === 'log' ? 'Rien dans le journal : lancez l’effet domino.' : 'Rien à signaler.'}</li>`}</ul>
          ${lr ? `<section class="dk-pp-card"><h3>Dernier passage <small>${esc(lr.status)}${lr.ms != null ? ` · ${lr.ms} ms` : ''}</small></h3>${lr.inputs ? `<div class="sub">entrées</div>${D.Inspector ? `<pre class="dk-json">${D.jsonHTML(lr.inputs)}</pre>` : ''}` : ''}${lr.outputs ? `<div class="sub">sorties</div><pre class="dk-json">${D.jsonHTML(lr.outputs)}</pre>` : ''}</section>` : ''}`;
      }
      this.side.innerHTML = `<header class="dk-pp-head"><div class="eyebrow">${esc(def.category)} · ${esc(sem.label)}${def.container ? ` · ${esc(def.container.kind)}` : ''}</div>
          <input class="dk-pp-name" value="${esc(ws.titleOf(n))}" aria-label="Nom de la pierre" data-keep="pp-name">
          <div class="dk-chips"><span class="dk-chip"><code>${esc(n.type)}</code></span><span class="dk-chip">${left.length} | ${right.length}</span>${errs.length ? `<span class="dk-chip err">${D.plural(errs.length, 'erreur')}</span>` : ''}${warns.length ? `<span class="dk-chip warn">${D.plural(warns.length, 'avertissement')}</span>` : ''}</div>
          <button class="dk-pp-x" data-act="close" aria-label="Fermer (Échap)">×</button></header>
        <div class="dk-pp-tabs" role="tablist">${tabs.map(([k, l]) => `<button role="tab" data-act="tab" data-t="${k}" aria-selected="${this.tab === k}">${l}</button>`).join('')}</div>
        <div class="dk-pp-body">${body}</div>
        <footer class="dk-pp-foot"><button class="dk-btn" data-act="inspect">Inspecter</button>${this.ed.insideOf(n) || n.type === 'domino.project' || n.type === 'domino.ref' ? `<button class="dk-btn" data-act="open">${n.type === 'domino.project' ? 'Ouvrir le projet' : n.type === 'domino.ref' ? 'Aller à la cible' : def.instanceOf ? 'Ouvrir sa déclaration' : def.callOf ? 'Ouvrir la fonction' : def.variableOf ? 'Voir sa déclaration' : def.kind === 'declaration' ? 'Ouvrir le corps' : 'Ouvrir l’intérieur'}</button>` : ''}<button class="dk-btn" data-act="dup">Dupliquer</button><button class="dk-btn danger" data-act="del">Supprimer</button></footer>`;
      D.ui.wireFields(this.side, ws, n, this.ed);
      D.ui.wireAbout(this.side, ws, n);
      const name = this.side.querySelector('.dk-pp-name');
      name.addEventListener('change', () => ws.setLabel(n.id, name.value.trim() === def.name ? '' : name.value.trim()));
      this.side.querySelectorAll('[data-link]').forEach((inp) => inp.addEventListener('change', () => ws.setLink(p.id, n.parent.pip, { [inp.dataset.link]: inp.type === 'checkbox' ? inp.checked : inp.value.trim() })));
    }

    // -------------------------------------------------------------------------
    _click(e) {
      const b = e.target.closest('[data-act], [data-focus], .t-pip-hit');
      if (!b) return;
      const n = this.ws.get(this.id);
      if (b.classList && b.classList.contains('t-pip-hit')) { this.pip = { side: b.dataset.side, i: +b.dataset.i }; this.tab = 'points'; this.render(); return; }
      if (b.dataset.focus) { this.focus(b.dataset.focus); return; }
      const act = b.dataset.act;
      if (act === 'close') this.close();
      else if (act === 'crumb' || act === 'go') this.focus(b.dataset.id);
      else if (act === 'tab') { this.tab = b.dataset.t; this.render(); }
      else if (act === 'dtab') { this.dtab = b.dataset.t; this.render(); }
      else if (act === 'pip') { this.pip = { side: b.dataset.side, i: +b.dataset.i }; this.render(); }
      else if (act === 'turn') this.ed.turn(n.id, b.dataset.d || null);
      else if (act === 'add') {
        const r = b.getBoundingClientRect();
        this.ed.quickAdd({ x: r.left, y: r.bottom, slot: { parent: n.id, via: b.dataset.via, pip: b.dataset.pip != null ? +b.dataset.pip : undefined } });
      } else if (act === 'inspect') { const id = n.id; this.close(true); this.ed.inspector.open('elements', id); }
      else if (act === 'open') { this.close(true); this.ed.openInside(n); }
      else if (act === 'wblock') { this.ws.setWire(b.dataset.w, { blocking: b.dataset.v === '1' }); this.render(); }
      else if (act === 'wdel') { this.ed.removeWire(b.dataset.w); this.render(); }
      else if (act === 'dup') { const c = this.ed.duplicate(n.id); this.focus(c.id); }
      else if (act === 'del') { const p = this.ws.parentOf(n); this.ed.remove(n.id); if (p) this.focus(p.id); else this.close(true); }
    }
    _key(e) {
      if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); if (!this.ed.quick.hidden) this.ed.hideQuick(); else this.close(); return; }
      if (e.key === 'Tab') {
        const f = [...this.layer.querySelectorAll('button:not([disabled]), input, select, [tabindex="0"]')].filter((x) => x.offsetParent !== null || x.closest('svg'));
        if (!f.length) return;
        const i = f.indexOf(document.activeElement);
        if (e.shiftKey && i <= 0) { e.preventDefault(); f[f.length - 1].focus(); } else if (!e.shiftKey && i === f.length - 1) { e.preventDefault(); f[0].focus(); }
        return;
      }
      if (e.key === 'Enter' && e.target.closest && e.target.closest('[data-focus], .dk-pp-ph')) { e.preventDefault(); e.target.closest('[data-focus], .dk-pp-ph').dispatchEvent(new MouseEvent('click', { bubbles: true })); return; }
      const tag = (e.target.tagName || '').toLowerCase();
      if (tag === 'input' || tag === 'select' || tag === 'textarea' || !e.key.startsWith('Arrow')) return;
      const n = this.ws.get(this.id), ws = this.ws;
      let to = null;
      if (e.key === 'ArrowRight') to = n.next.find(Boolean) && n.next.find(Boolean).id;
      else if (e.key === 'ArrowLeft') to = n.parent && n.parent.via === 'next' ? n.parent.id : null;
      else if (e.key === 'ArrowUp') to = (n.top[0] && n.top[0].id) || (n.parent && n.parent.via === 'bottom' ? n.parent.id : null);
      else if (e.key === 'ArrowDown') to = (n.bottom[0] && n.bottom[0].id) || (n.parent && n.parent.via === 'top' ? n.parent.id : null);
      if (to && ws.get(to)) { e.preventDefault(); this.focus(to); this.ed._say(`« ${ws.titleOf(ws.get(to))} » prise en main.`); }
    }
    destroy() { this._off(); this.layer.remove(); }
  }

  D.Popup = Popup;
})(typeof globalThis !== 'undefined' ? globalThis : window);
