/*!
 * Zeugma · gabarits du studio
 *
 * Le balisage de l'application (en-tête et barre d'outils, barre d'état, page de bienvenue, volet vide),
 * déclaré dans le même registre que les gabarits des composants (Domino.Templates, engine/ui/domino.templates.js) :
 * Domino.Templates.list() les montre tous, override() les remplace un par un.
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const T = D.Templates;

  T.defineIcons({

    undo: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M5.5 3.5 2.5 6.5l3 3"/><path d="M2.5 6.5h7a4 4 0 0 1 0 8H7"/></svg>',
    redo: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="m10.5 3.5 3 3-3 3"/><path d="M13.5 6.5h-7a4 4 0 0 0 0 8H9"/></svg>',
    run: '<svg viewBox="0 0 16 16" fill="currentColor"><path d="M4.5 2.8v10.4a.6.6 0 0 0 .9.5l8.2-5.2a.6.6 0 0 0 0-1L5.4 2.3a.6.6 0 0 0-.9.5Z"/></svg>',
    stop: '<svg viewBox="0 0 16 16" fill="currentColor"><rect x="3.5" y="3.5" width="9" height="9" rx="1.5"/></svg>',
    insp: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="2" y="2.5" width="12" height="11" rx="1.5"/><path d="M2 9h12"/></svg>',
    theme: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4"><circle cx="8" cy="8" r="5.5"/><path d="M8 2.5a5.5 5.5 0 0 0 0 11Z" fill="currentColor"/></svg>',
    burger: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M2.5 4h11M2.5 8h11M2.5 12h11"/></svg>',
    split: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4"><rect x="2" y="2.5" width="12" height="11" rx="1.5"/><path d="M8 2.5v11"/></svg>',
    pioche: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4"><rect x="2" y="2.5" width="12" height="11" rx="1.5"/><path d="M6 2.5v11"/></svg>',
    brand: '<svg width="40" height="22" viewBox="0 0 40 22" aria-hidden="true"><rect x="1" y="2.5" width="38" height="17" rx="3.4" fill="#D6D2C4"/><rect x="1" y="1" width="38" height="17" rx="3.4" fill="#FBFAF5" stroke="#CBC6B7"/><line x1="20" y1="4" x2="20" y2="15" stroke="#C9C4B5" stroke-width="1.2"/><circle cx="20" cy="9.5" r="1.6" fill="#B8893B"/><circle cx="10.5" cy="9.5" r="2" fill="#E5484D"/><circle cx="26" cy="5" r="1.7" fill="#151718"/><circle cx="34" cy="14" r="1.7" fill="#3B7DDD"/><circle cx="30" cy="9.5" r="1.7" fill="#151718"/></svg>',
  });

  T.define('studio.shell', (d, h) => h.html`
    <header class="st-top">
      <div class="st-brand">${h.icon('brand')}<div class="st-brand-name">${h.raw(d.brand || 'Domino <span>Studio</span>')}</div></div>
      <button type="button" class="st-icon st-burger" aria-label="Menus" aria-haspopup="menu">${h.icon('burger')}</button>
      <nav class="st-menubar"></nav>
      <div class="st-doc" aria-live="off"><span class="st-doc-dot"></span><b class="st-doc-title"></b><small class="st-doc-lang"></small></div>
      <div class="st-spacer"></div>
      <div class="st-quick" role="toolbar" aria-label="Actions rapides">
        <button type="button" class="st-icon" data-cmd="edit.undo" aria-label="Annuler">${h.icon('undo')}</button>
        <button type="button" class="st-icon" data-cmd="edit.redo" aria-label="Rétablir">${h.icon('redo')}</button>
        <button type="button" class="st-icon hide-sm" data-cmd="view.pioche" aria-label="Boîte à outils">${h.icon('pioche')}</button>
        <button type="button" class="st-icon hide-sm" data-cmd="view.splitRight" aria-label="Diviser à droite">${h.icon('split')}</button>
        <button type="button" class="btn primary st-run" data-cmd="run.run">${h.icon('run')}<span>Effet domino</span></button>
        <button type="button" class="st-icon st-stop" data-cmd="run.stop" aria-label="Arrêter" hidden>${h.icon('stop')}</button>
        <button type="button" class="st-icon" data-cmd="view.inspector" aria-label="Inspecteur">${h.icon('insp')}</button>
        <button type="button" class="st-icon" data-cmd="view.themeToggle" aria-label="Basculer le thème clair ou sombre">${h.icon('theme')}</button>
      </div>
    </header>
    <div class="st-banner" role="status" hidden></div>
    <main class="st-main"></main>
    <footer class="st-status" aria-label="Barre d’état"></footer>`,
  { description: 'La coque du studio : marque, barre de menus, document actif, actions rapides, zone des volets, barre d’état.', data: '{ brand? (HTML) }' });

  T.define('studio.status', (d, h) => h.html`
    <button type="button" class="st-sb${d.storage.degraded ? ' warn' : ''}" data-cmd="file.storageInfo" title="Où sont enregistrés les projets">${d.storage.degraded ? '⚠ ' : ''}Stockage : ${d.storage.label}</button>
    ${d.doc ? h.html`<button type="button" class="st-sb${d.doc.dirty ? ' dirty' : ''}" data-cmd="file.save" title="${`Enregistrer (${d.doc.saveKey})`}">${d.doc.save}</button>` : ''}
    <span class="st-grow"></span>
    ${d.groups && d.groups.count > 1 ? h.html`<button type="button" class="st-sb" data-cmd="view.focusNextGroup" title="Volet suivant">Volet ${d.groups.index}/${d.groups.count}</button>` : ''}
    ${d.mode ? h.html`<button type="button" class="st-sb" data-cmd="view.displayMenu" title="${`Affichage des pierres (${d.mode.key}…)`}">◫ ${d.mode.label}</button>` : ''}
    ${d.language ? h.html`<button type="button" class="st-sb" data-cmd="lang.show" title="Voir le langage"><span class="st-swatch" style="--c:${d.language.color}"></span>${d.language.name}</button>` : ''}
    <button type="button" class="st-sb" data-cmd="view.palette" title="Toutes les commandes">${d.paletteKey} Commandes</button>`,
  { description: 'La barre d’état du studio : stockage, enregistrement, volets, affichage, langage, palette.', data: '{ storage: { label, degraded }, doc?: { dirty, save, saveKey }, groups?: { index, count }, mode?: { label, key }, language?: { name, color }, paletteKey }' });

  T.define('studio.welcome', (d, h) => h.html`<div class="st-welcome"><div class="st-w-in">
    <header><h1>Domino <span>Studio</span></h1><p>Construisez des langages visuels avec des dominos : chaque pierre est un élément, ses points sont ses entrées et ses sorties, la chaîne est le programme.</p></header>
    <div class="st-w-cols">
      <section><h2>Démarrer</h2><div class="st-w-actions">
        <button type="button" class="btn primary" data-cmd="file.new">Nouveau projet… <kbd>${d.keys.new}</kbd></button>
        <button type="button" class="btn" data-cmd="file.open">Ouvrir un projet… <kbd>${d.keys.open}</kbd></button>
        <button type="button" class="btn" data-cmd="file.openFile">Ouvrir un fichier… <kbd>${d.keys.openFile}</kbd></button>
        <button type="button" class="btn" data-cmd="view.palette">Toutes les commandes <kbd>${d.keys.palette}</kbd></button></div>
        <h2>Récents</h2>${d.recent.length
    ? h.html`<ul class="st-w-recent">${d.recent.map((r) => h.html`<li><button type="button" data-uri="${r.uri}"><span class="st-swatch" style="--c:${r.color}"></span><b>${r.title}</b><small>${r.language} · ${r.when}</small></button></li>`)}</ul>`
    : h.html`<p class="st-hint">Les projets enregistrés (Ctrl+S) apparaîtront ici.</p>`}
        <h2>Raccourcis essentiels</h2><ul class="st-w-keys"><li><kbd>${d.keys.save}</kbd> enregistrer</li><li><kbd>${d.keys.split}</kbd> diviser à droite</li><li><kbd>${d.keys.goto}</kbd> aller à un élément</li><li><kbd>${d.keys.run}</kbd> effet domino</li><li><kbd>Ctrl</kbd>+<kbd>glisser</kbd> sélectionner</li><li><kbd>F6</kbd> région suivante</li><li><kbd>Alt</kbd> barre de menus</li></ul>
        <label class="st-check"><input type="checkbox" data-pref="welcome" ${d.showWelcome ? 'checked' : ''}> Afficher cette page quand rien n’est ouvert</label></section>
      <section><h2>Créer un éditeur</h2><p class="st-hint">Un modèle, puis le Concepteur : des dominos qui décrivent votre éditeur, l’aperçu à côté, sans écrire de code. <kbd>${d.keys.designer}</kbd></p>
        <div class="st-pat compact">${d.patterns.map((p) => h.html`<button type="button" class="st-pat-card" data-design="${p.id}" style="--c:${p.color}"><span class="ic" aria-hidden="true">${p.icon || '◆'}</span><b>${p.name}</b></button>`)}<button type="button" class="st-pat-card" data-design="vierge" style="--c:#8A8F8C"><span class="ic" aria-hidden="true">＋</span><b>Vierge</b></button></div>
        <h2>Langages</h2><div class="st-w-langs">${d.groups.map((g) => h.html`<h3>${g.label}</h3>${g.languages.map((L) => h.html`<article class="st-w-lang" style="--c:${L.color}"><div><b>${L.name}</b><p>${L.description}</p></div><div class="st-w-tpl">${L.templates.map((t) => h.html`<button type="button" class="btn${t.id === 'example' ? ' primary' : ''}" data-new="${L.id}" data-tpl="${t.id}">${t.id === 'example' ? 'Exemple' : t.name}</button>`)}</div></article>`)}`)}</div></section>
    </div></div></div>`,
  { description: 'La page de bienvenue : démarrer, récents, raccourcis, modèles du Concepteur, langages.', data: '{ keys, recent: [{ uri, title, color, language, when }], showWelcome, patterns: [{ id, name, color, icon }], groups: [{ label, languages: [{ id, name, color, description, templates: [{ id, name }] }] }] }' });

  T.define('studio.emptyGroup', (d, h) => h.html`<div class="st-empty-group"><p>Aucun onglet dans ce volet.</p><div><button type="button" class="btn primary" data-cmd="file.new">Nouveau projet…</button> <button type="button" class="btn" data-cmd="file.open">Ouvrir…</button> <button type="button" class="btn" data-cmd="view.welcome">Bienvenue</button></div><p class="st-hint">Glissez un onglet ici, ou un fichier .json depuis votre ordinateur.</p></div>`,
    { description: 'Un volet sans onglet.', data: '{}' });
})(typeof globalThis !== 'undefined' ? globalThis : window);
