/*
 * Zeugma — kit de rendu des pierres (maquettes de design).
 * Ce fichier ne fait que dessiner des pierres en SVG pour le design system et la démo.
 * Ce n'est pas le cœur de la bibliothèque.
 *
 * Une pierre est un vrai domino : deux faces carrées, une ligne de partage, un pivot en laiton.
 * Rien n'est écrit sur la pierre ; son nom s'affiche en entête, au-dessus d'elle.
 */
(function (global) {
  'use strict';

  // Palette fixe : couleurs de connecteurs (catégories) et couleurs de points.
  const CAT = {
    rouge: '#E5484D',
    orange: '#EE7D2F',
    ambre: '#E2A812',
    vert: '#38A169',
    sarcelle: '#13A3A0',
    bleu: '#3B7DDD',
    indigo: '#6A5BDC',
    rose: '#D9539A',
    ardoise: '#5E6E7A',
  };

  // Disposition des points sur la grille 3×3 (colonne, rangée), dans l'ordre de lecture :
  // de gauche à droite, puis de haut en bas. L'indice d'un point est son rang dans cette liste.
  // Au-delà de 6 : 9 points.
  const PIPS = {
    0: [],
    1: [[1, 1]],
    2: [[0, 0], [2, 2]],
    3: [[0, 0], [1, 1], [2, 2]],
    4: [[0, 0], [2, 0], [0, 2], [2, 2]],
    5: [[0, 0], [2, 0], [1, 1], [0, 2], [2, 2]],
    6: [[0, 0], [2, 0], [0, 1], [2, 1], [0, 2], [2, 2]],
    9: [[0, 0], [1, 0], [2, 0], [0, 1], [1, 1], [2, 1], [0, 2], [1, 2], [2, 2]],
  };
  const faceKey = (n) => (n > 6 ? 9 : Math.max(0, n | 0));

  const SKINS = {
    ivoire: {
      face: '#FBFAF5', side: '#D6D2C4', edge: '#CBC6B7', pip: '#151718', divider: '#CBC6B8',
      pin: '#B8893B', text: '#26292A', gloss: 'rgba(255,255,255,.95)',
    },
    ebene: {
      face: '#1F2122', side: '#090A0A', edge: '#383C3E', pip: '#F4F1E8', divider: '#43474A',
      pin: '#C99A4A', text: '#EEEBE3', gloss: 'rgba(255,255,255,.10)',
    },
  };
  const CONTAINER = '#E1E4E6';

  const FONT_D = "'Bricolage Grotesque', 'Segoe UI', system-ui, sans-serif";

  function esc(s) {
    return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  }
  function rgb(h) {
    h = h.replace('#', '');
    if (h.length === 3) h = h.split('').map((c) => c + c).join('');
    const n = parseInt(h, 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  }
  function mix(a, b, t) {
    const A = rgb(a), B = rgb(b);
    return '#' + A.map((v, i) => Math.round(v + (B[i] - v) * t).toString(16).padStart(2, '0')).join('');
  }
  function lum(h) {
    const [r, g, b] = rgb(h).map((v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  }
  // Construit un habillage complet à partir d'une seule couleur de face.
  function paint(face) {
    const dark = lum(face) < 0.2;
    return {
      face,
      side: mix(face, '#000000', dark ? 0.55 : 0.17),
      edge: dark ? mix(face, '#FFFFFF', 0.12) : mix(face, '#000000', 0.1),
      divider: dark ? mix(face, '#FFFFFF', 0.16) : mix(face, '#000000', 0.15),
      pip: dark ? '#F4F1E8' : '#151718',
      pin: '#B8893B',
      text: dark ? '#F1EEE6' : '#26292A',
      gloss: dark ? 'rgba(255,255,255,.1)' : 'rgba(255,255,255,.8)',
    };
  }
  function skinFor(d, o) {
    if (d.tint) return paint(d.tint);
    if (d.container) return paint(o.containerColor || CONTAINER);
    if (o.skin === 'teinte') {
      const c = (d.outColors && d.outColors[0]) || (d.inColors && d.inColors[0]) || '#9AA3A0';
      return paint(mix('#FFFFFF', c, 0.22));
    }
    return SKINS[o.skin] || SKINS.ivoire;
  }

  let ctx = null;
  const mcache = new Map();
  function measure(text, font) {
    const k = font + '|' + text;
    if (mcache.has(k)) return mcache.get(k);
    ctx = ctx || document.createElement('canvas').getContext('2d');
    ctx.font = font;
    const w = ctx.measureText(text).width;
    // Un cache borné : au-delà de 20 000 mesures, on repart de zéro (les grands projets n'enflent pas la mémoire).
    if (mcache.size > 20000) mcache.clear();
    mcache.set(k, w);
    return w;
  }
  const fcache = new Map();
  /** Le plus long début du texte qui tient (avec « … ») : recherche dichotomique, résultat mémorisé. */
  function fitText(t, font, max) {
    if (measure(t, font) <= max) return t;
    const key = `${font}|${max}|${t}`;
    if (fcache.has(key)) return fcache.get(key);
    let lo = 1, hi = t.length - 1;
    while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (measure(t.slice(0, mid) + '…', font) <= max) lo = mid; else hi = mid - 1; }
    const out = t.slice(0, lo) + '…';
    if (fcache.size > 20000) fcache.clear();
    fcache.set(key, out);
    return out;
  }

  const depth = (T) => Math.max(2, T * 0.075);

  // Entête : taille du texte, place réservée, largeur réelle.
  function headInfo(d, o, W, T) {
    const where = o.header === undefined || o.header === true ? 'top' : o.header;
    if (!where || !d.name) return { where: null, size: 0, space: 0, w: 0 };
    const size = o.headerSize || Math.max(9, Math.round(T * 0.18 * 10) / 10);
    const font = `600 ${size}px ${FONT_D}`;
    const icon = d.container ? size * 1.25 : 0;
    const max = (o.headerMax || (where === 'right' ? T * 5 : W + T * 0.3)) - icon;
    const text = fitText(d.name, font, Math.max(size * 2, max));
    const w = measure(text, font) + icon;
    return { where, size, font, icon, text, w, space: where === 'right' ? 0 : size * 1.3 + 4 };
  }

  /**
   * Dimensions d'une pierre.
   * Renvoie { W, H, D, T, head, headW, headWhere } : W × H est la face vue de dessus,
   * T l'épaisseur (le petit côté), head la place réservée à l'entête.
   */
  function layoutTile(d, o = {}) {
    const T = o.H || 72;
    const v = o.orient === 'v';
    const W = v ? T : 2 * T, H = v ? 2 * T : T;
    const hi = headInfo(d, o, W, T);
    return { W, H, D: depth(T), T, head: hi.space, headW: hi.w, headWhere: hi.where };
  }

  // Passe du repère des faces (2T × T, entrée à gauche) au repère de la pierre posée.
  // Horizontale : entrée à gauche, ou à droite si elle est retournée (flip).
  // Verticale : entrée en haut, ou en bas si elle est retournée.
  function frame(T, orient, flip) {
    if (orient === 'v') return flip ? { t: `translate(0 ${2 * T}) rotate(-90)`, f: (x, y) => [y, 2 * T - x] } : { t: `translate(${T} 0) rotate(90)`, f: (x, y) => [T - y, x] };
    return flip ? { t: `translate(${2 * T} ${T}) rotate(180)`, f: (x, y) => [2 * T - x, T - y] } : { t: '', f: (x, y) => [x, y] };
  }

  // Coordonnées des points d'une face, dans le repère de la pierre posée.
  function pipXY(count, side, T = 72, orient = 'h', flip = false) {
    const ox = side === 'in' ? 0 : T, F = frame(T, orient, flip).f;
    return PIPS[faceKey(count)].map(([c, r], i) => {
      const [x, y] = F(ox + T * (0.27 + 0.23 * c), T * (0.27 + 0.23 * r));
      return { i, x, y, r: T * 0.068 };
    });
  }

  // Demi-pierre aux coins extérieurs arrondis : la face d'entrée (gauche) ou de sortie (droite).
  function halfPath(x, y, w, h, r, side) {
    return side === 'in'
      ? `M${x + r} ${y}H${x + w}V${y + h}H${x + r}A${r} ${r} 0 0 1 ${x} ${y + h - r}V${y + r}A${r} ${r} 0 0 1 ${x + r} ${y}Z`
      : `M${x} ${y}H${x + w - r}A${r} ${r} 0 0 1 ${x + w} ${y + r}V${y + h - r}A${r} ${r} 0 0 1 ${x + w - r} ${y + h}H${x}Z`;
  }
  // Couleur de point lisible sur une face : noir sur fond clair, ivoire sur fond sombre.
  const pipOn = (face) => ((lum(face) + 0.05) / 0.058 >= 0.93 / (lum(face) + 0.05) ? '#151718' : '#F4F1E8');

  // Points d'une face. colors[i] fixe la couleur du point i ; vide = couleur par défaut (noir sur ivoire).
  function pips(n, colors, side, T, def, hit) {
    const ox = side === 'in' ? 0 : T;
    const r = T * 0.068;
    return PIPS[faceKey(n)].map(([c, rw], i) => {
      const cx = (ox + T * (0.27 + 0.23 * c)).toFixed(2), cy = (T * (0.27 + 0.23 * rw)).toFixed(2);
      const col = colors && colors[i];
      const ring = col ? ` stroke="${mix(col, '#000000', 0.32)}" stroke-width="${(r * 0.16).toFixed(2)}"` : '';
      const pip = `<circle class="t-pip" data-side="${side}" data-i="${i}" cx="${cx}" cy="${cy}" r="${r.toFixed(2)}" fill="${col || def}"${ring}/>`;
      return hit ? pip + `<circle class="t-pip-hit" data-side="${side}" data-i="${i}" cx="${cx}" cy="${cy}" r="${(r * 2).toFixed(2)}" fill="transparent"/>` : pip;
    }).join('');
  }

  // Bande de connecteurs : un petit trait par couleur, 4 par colonne ; chaque colonne élargit la bande.
  function strip(colors, side, W, T) {
    if (!colors || !colors.length) return '';
    const per = 4, bw = T * 0.12, bh = Math.max(2, T * 0.046), pitch = T * 0.095, colStep = bw + T * 0.03;
    let s = `<g class="t-strip t-strip-${side}">`;
    colors.forEach((c, i) => {
      const col = Math.floor(i / per), row = i % per;
      const inCol = Math.min(per, colors.length - col * per);
      const y = T / 2 - ((inCol - 1) * pitch) / 2 + row * pitch - bh / 2;
      const x = side === 'in' ? -bw * 0.45 + col * colStep : W - bw * 0.55 - col * colStep;
      s += `<rect x="${x.toFixed(2)}" y="${y.toFixed(2)}" width="${bw.toFixed(2)}" height="${bh.toFixed(2)}" rx="${(bh / 2).toFixed(2)}" fill="${c}" stroke="rgba(0,0,0,.28)" stroke-width=".5"/>`;
    });
    return s + '</g>';
  }

  function plural(n, w) { return `${n} ${w}${n > 1 ? 's' : ''}`; }

  // Entête : le nom de la pierre, posé au-dessus (ou à côté) d'elle. Les pierres conteneurs ont un petit pictogramme de pile.
  function headerSVG(d, hi, W, H, D, s) {
    if (!hi.where) return '';
    const fs = hi.size;
    let x, y;
    const anchor = 'start';
    if (hi.where === 'right') { x = W + fs * 0.6; y = H / 2 + fs * 0.35; }
    else {
      x = W / 2 - hi.w / 2;
      y = hi.where === 'bottom' ? H + D + fs * 1.1 + 2 : -fs * 0.45 - 4;
    }
    let icon = '';
    if (hi.icon) {
      const iw = fs * 0.82, ih = fs * 0.5, iy = y - fs * 0.62;
      icon = `<g class="t-head-ico" fill="none" stroke="currentColor" stroke-width="${(fs * 0.1).toFixed(2)}">`
        + `<rect x="${(x + fs * 0.16).toFixed(2)}" y="${(iy - fs * 0.16).toFixed(2)}" width="${iw.toFixed(2)}" height="${ih.toFixed(2)}" rx="${(fs * 0.1).toFixed(2)}" opacity=".55"/>`
        + `<rect x="${x.toFixed(2)}" y="${iy.toFixed(2)}" width="${iw.toFixed(2)}" height="${ih.toFixed(2)}" rx="${(fs * 0.1).toFixed(2)}"/></g>`;
    }
    const fam = FONT_D.replace(/"/g, "'");
    return `<g class="t-head" fill="${s.text}" color="${s.text}">${icon}<text x="${(x + hi.icon).toFixed(2)}" y="${y.toFixed(2)}" text-anchor="${anchor}" font-family="${fam}" font-weight="600" font-size="${fs}">${esc(hi.text)}</text></g>`;
  }

  /**
   * Dessine une pierre. Renvoie { svg, W, H, D, T, head } ; svg est le contenu à placer dans un <g>.
   * d : { name, inputs, outputs, inColors[], outColors[], inPips[], outPips[], inFace, outFace, container, tint }
   *     inPips / outPips : couleur de chaque point (vide ou null = couleur par défaut).
   *     inFace / outFace : couleur de la face gauche (entrées) et de la face droite (sorties) ; vide = habillage.
   * o : { H (épaisseur), orient: 'h'|'v', flip, overflow: 'nine'|'engrave', skin, containerColor, mini, badge: 'warn'|'error'|null,
   *       header: true|false|'top'|'bottom'|'right', headerSize, headerMax, pipHit, title }
   * En orientation verticale ('v'), la face d'entrée est en haut et la face de sortie en bas.
   * flip retourne la pierre : entrée à droite (horizontale) ou en bas (verticale), comme après un virage.
   */
  function tileSVG(d, o = {}) {
    const L = layoutTile(d, o);
    const { W, H, D, T } = L;
    const v = o.orient === 'v';
    const s = skinFor(d, o);
    const r = T * 0.13;
    const pad = T * 0.08;
    const out = [];
    out.push(`<rect class="t-ring" fill="none" x="${-pad}" y="${-pad}" width="${W + 2 * pad}" height="${H + D + 2 * pad}" rx="${r + pad}"/>`);
    if (d.container && !o.mini) {
      const p = T * 0.085;
      out.push(`<rect x="${p}" y="${-p}" width="${W}" height="${H}" rx="${r}" fill="${s.side}" stroke="${s.edge}" stroke-width="1"/>`);
    }
    // Chaque moitié peut avoir sa propre couleur ; ses points par défaut restent lisibles dessus.
    const fIn = d.inFace ? paint(d.inFace) : null, fOut = d.outFace ? paint(d.outFace) : null;
    const flip = !!o.flip;
    const lead = flip ? fOut : fIn, trail = flip ? fIn : fOut; // moitié gauche/haute, moitié droite/basse
    out.push(`<rect x="0" y="${D}" width="${W}" height="${H}" rx="${r}" fill="${(v ? trail : null)?.side || s.side}"/>`);
    if (!v) {
      if (lead) out.push(`<path d="${halfPath(0, D, T, H, r, 'in')}" fill="${lead.side}"/>`);
      if (trail) out.push(`<path d="${halfPath(T, D, T, H, r, 'out')}" fill="${trail.side}"/>`);
    }
    out.push(`<rect class="t-face" x="0" y="0" width="${W}" height="${H}" rx="${r}" fill="${s.face}" stroke="${s.edge}" stroke-width="1"/>`);

    // Contenu des faces, dessiné à l'horizontale (2T × T) puis tourné si la pierre est verticale ou retournée.
    const sw = Math.max(1, T * 0.022);
    const c = [];
    if (fIn) c.push(`<path class="t-half" d="${halfPath(0, 0, T, T, r, 'in')}" fill="${fIn.face}" stroke="${fIn.edge}" stroke-width="1"/>`);
    if (fOut) c.push(`<path class="t-half" d="${halfPath(T, 0, T, T, r, 'out')}" fill="${fOut.face}" stroke="${fOut.edge}" stroke-width="1"/>`);
    if (o.pipHit) c.push(`<rect class="t-face-hit" data-side="in" x="0" y="0" width="${T}" height="${T}" fill="transparent"/><rect class="t-face-hit" data-side="out" x="${T}" y="0" width="${T}" height="${T}" fill="transparent"/>`);
    const div = fIn || fOut ? mix(fIn ? fIn.divider : s.divider, fOut ? fOut.divider : s.divider, 0.5) : s.divider;
    c.push(`<line x1="${T}" y1="${T * 0.17}" x2="${T}" y2="${T * 0.83}" stroke="${div}" stroke-width="${sw}" stroke-linecap="round"/>`);
    c.push(`<circle cx="${T}" cy="${T / 2}" r="${Math.max(1.6, T * 0.043)}" fill="${s.pin}"/><circle cx="${T - T * 0.012}" cy="${T / 2 - T * 0.014}" r="${Math.max(0.6, T * 0.014)}" fill="#FFFFFF" opacity=".6"/>`);
    c.push(pips(d.inputs, d.inPips, 'in', T, fIn ? pipOn(d.inFace) : s.pip, o.pipHit), pips(d.outputs, d.outPips, 'out', T, fOut ? pipOn(d.outFace) : s.pip, o.pipHit));
    // Option overflow: 'engrave' : au-delà de 6, la valeur exacte est gravée dans le coin de la face.
    if (o.overflow === 'engrave') for (const [side, v] of [['in', d.inputs], ['out', d.outputs]]) {
      if (v <= 6) continue;
      const fc = (side === 'in' ? fIn : fOut) ? (side === 'in' ? d.inFace : d.outFace) : s.face;
      const fs = T * 0.15, x = (side === 'in' ? 0 : T) + T * 0.5, y = T * 0.97;
      c.push(`<g class="t-count" font-family="${FONT_D.replace(/"/g, "'")}" font-weight="700" font-size="${fs.toFixed(2)}" text-anchor="middle">`
        + `<text x="${x.toFixed(2)}" y="${(y + 0.6).toFixed(2)}" fill="rgba(255,255,255,.7)">${v}</text>`
        + `<text x="${x.toFixed(2)}" y="${y.toFixed(2)}" fill="${mix(fc, '#000000', 0.45)}">${v}</text></g>`);
    }
    if (d.inputs > 0) c.push(strip(d.inColors, 'in', 2 * T, T));
    if (d.outputs > 0) c.push(strip(d.outColors, 'out', 2 * T, T));
    const fr = frame(T, v ? 'v' : 'h', flip);
    out.push(fr.t ? `<g transform="${fr.t}">${c.join('')}</g>` : c.join(''));
    const gloss = (v ? lead : lead || trail) ? 'rgba(255,255,255,.35)' : s.gloss;
    out.push(`<path d="M${r} 1.3H${W - r}" stroke="${gloss}" stroke-width="1.3" stroke-linecap="round" fill="none"/>`);

    if (o.badge) {
      const br = Math.max(5, T * 0.1);
      const col = o.badge === 'error' ? '#D93A3A' : '#D18A00';
      out.push(`<g class="t-badge"><circle cx="${W - br * 0.2}" cy="${br * 0.2}" r="${br}" fill="${col}" stroke="#FFFFFF" stroke-width="1.5"/><rect x="${W - br * 0.2 - br * 0.12}" y="${br * 0.2 - br * 0.55}" width="${br * 0.24}" height="${br * 0.68}" rx="${br * 0.12}" fill="#FFFFFF"/><circle cx="${W - br * 0.2}" cy="${br * 0.2 + br * 0.45}" r="${br * 0.13}" fill="#FFFFFF"/></g>`);
    }

    // L'entête peut être rendu à part (splitHead) pour rester net, hors du filtre d'ombre de la pierre.
    const hi = headInfo(d, o, W, T);
    const headSvg = headerSVG(d, hi, W, H, D, { text: o.headerColor || '#26292A' });
    if (!o.splitHead) out.push(headSvg);

    if (o.title !== false) {
      const io = `${plural(d.inputs, 'entrée')} · ${plural(d.outputs, 'sortie')}`;
      out.push(`<title>${esc(d.name || 'Pierre')} — ${io}</title>`);
    }
    return { svg: out.join(''), headSvg: o.splitHead ? headSvg : '', W, H, D, T, head: hi.space, headW: hi.w };
  }

  // Une face seule (carré), utile pour les spécimens du design system.
  function faceSVG(n, H = 64, skin = 'ivoire', colors = null) {
    const s = SKINS[skin] || SKINS.ivoire;
    const D = depth(H), r = H * 0.16;
    return `<svg class="dk-face" viewBox="-4 -4 ${H + 8} ${H + D + 8}" width="${H + 8}" height="${H + D + 8}" aria-label="${n} point(s)">`
      + `<g filter="url(#dk-shadow)"><rect x="0" y="${D}" width="${H}" height="${H}" rx="${r}" fill="${s.side}"/>`
      + `<rect x="0" y="0" width="${H}" height="${H}" rx="${r}" fill="${s.face}" stroke="${s.edge}"/>`
      + pips(n, colors, 'in', H, s.pip, false) + '</g></svg>';
  }

  // Une pierre autonome, dans son propre <svg>. La boîte englobe l'entête.
  function standalone(d, o = {}) {
    const t = tileSVG(d, { ...o, splitHead: true });
    const pad = o.pad ?? Math.ceil(t.T * 0.16) + 6;
    const L = layoutTile(d, o);
    const hx = L.headWhere === 'right' ? 0 : Math.max(0, (t.headW - t.W) / 2);
    const right = L.headWhere === 'right' ? t.headW + t.T * 0.2 : 0;
    const top = L.headWhere === 'top' ? t.head : 0, bottom = L.headWhere === 'bottom' ? t.head : 0;
    const x0 = -pad - hx, y0 = -pad - top;
    const w = t.W + pad * 2 + hx * 2 + right, h = t.H + t.D + pad * 2 + top + bottom;
    const sc = o.scale || 1;
    return `<svg class="dk ${o.svgClass || ''}" viewBox="${x0.toFixed(1)} ${y0.toFixed(1)} ${w.toFixed(1)} ${h.toFixed(1)}" width="${(w * sc).toFixed(1)}" height="${(h * sc).toFixed(1)}" role="img" aria-label="${esc(d.name || 'Pierre')}">`
      + `<g class="tile ${o.cls || ''}" ${o.shadow === false ? '' : `filter="url(#${o.lift ? 'dk-lift' : 'dk-shadow'})"`}>${t.svg}</g>${t.headSvg}</svg>`;
  }

  const DEFS = `<filter id="dk-shadow" x="-20%" y="-40%" width="140%" height="190%" color-interpolation-filters="sRGB"><feDropShadow dx="0" dy="2" stdDeviation="2" flood-color="#0B1410" flood-opacity=".2"/></filter>`
    + `<filter id="dk-lift" x="-30%" y="-60%" width="160%" height="240%" color-interpolation-filters="sRGB"><feDropShadow dx="0" dy="12" stdDeviation="9" flood-color="#0B1410" flood-opacity=".3"/></filter>`;

  // Injecte une seule fois les filtres d'ombre partagés par toutes les pierres de la page.
  function injectDefs() {
    if (document.getElementById('dk-defs')) return;
    const holder = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    holder.setAttribute('id', 'dk-defs');
    holder.setAttribute('width', '0');
    holder.setAttribute('height', '0');
    holder.setAttribute('aria-hidden', 'true');
    holder.style.position = 'absolute';
    holder.innerHTML = `<defs>${DEFS}</defs>`;
    document.body.prepend(holder);
  }

  global.DominoKit = {
    CAT, PIPS, SKINS, CONTAINER, faceKey, esc, mix, lum, paint, pipOn, depth, measure, fitText,
    layoutTile, tileSVG, faceSVG, standalone, pipXY, injectDefs, clearCache: () => { mcache.clear(); fcache.clear(); },
  };
})(window);
