/*!
 * Zeugma · sélection multiple (sans DOM)
 *
 *   const s = new Domino.Selection();
 *   s.set(['a']);  s.toggle('b');  s.add(['c', 'd']);  s.ids  // ['a', 'b', 'c', 'd'], s.primary === 'b'
 *
 * Une sélection est un ensemble ordonné d'identifiants de pierres et une pierre principale (la dernière
 * désignée : c'est elle que l'inspecteur montre et que le clavier fait bouger). Elle émet « change ».
 *
 * Les fonctions statiques font le travail qui ne dépend pas de l'écran : rectangle normalisé, pierres
 * touchées par un rectangle de sélection, racines d'une sélection, presse-papiers de plusieurs pierres.
 * La vue (domino.view.js) s'occupe des gestes : Ctrl + clic, Ctrl + glisser (bouton gauche ou droit).
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const CLIP_FORMAT = 'kantoaplo.domino.clip';

  class Selection extends D.Emitter {
    constructor(ids = []) {
      super();
      /** @type {Set<string>} */
      this._ids = new Set();
      /** @type {string|null} */
      this.primary = null;
      if (ids.length) this.set(ids);
    }
    get ids() { return [...this._ids]; }
    get size() { return this._ids.size; }
    get empty() { return this._ids.size === 0; }
    get multiple() { return this._ids.size > 1; }
    has(id) { return this._ids.has(id); }

    /** Remplace la sélection. `primary` : la pierre principale (la dernière de la liste par défaut). */
    set(ids, primary) {
      const list = [...new Set((ids || []).filter(Boolean))];
      const next = primary && list.includes(primary) ? primary : list[list.length - 1] || null;
      if (sameSet(this._ids, list) && next === this.primary) return false;
      this._ids = new Set(list);
      this.primary = next;
      this._changed();
      return true;
    }
    /** Ajoute des pierres ; la dernière ajoutée devient principale. */
    add(ids) {
      const list = [].concat(ids || []).filter(Boolean);
      const before = this._ids.size;
      for (const id of list) this._ids.add(id);
      const primary = list.length ? list[list.length - 1] : this.primary;
      if (this._ids.size === before && primary === this.primary) return false;
      this.primary = primary;
      this._changed();
      return true;
    }
    /** Retire des pierres ; si la principale part, la précédente dans l'ordre la remplace. */
    remove(ids) {
      let changed = false;
      for (const id of [].concat(ids || [])) changed = this._ids.delete(id) || changed;
      if (!changed) return false;
      if (!this._ids.has(this.primary)) this.primary = this.ids[this._ids.size - 1] || null;
      this._changed();
      return true;
    }
    /** Ctrl + clic : ajoute la pierre si elle n'y est pas, la retire sinon. */
    toggle(id) { return this._ids.has(id) ? this.remove(id) : this.add(id); }
    clear() { return this.set([]); }
    /** Retire ce qui n'existe plus (après une suppression, une annulation). */
    prune(exists) { const gone = this.ids.filter((id) => !exists(id)); return gone.length ? this.remove(gone) : false; }
    toJSON() { return { ids: this.ids, primary: this.primary }; }
    _changed() { this.emit('change', { ids: this.ids, primary: this.primary }); }
  }
  const sameSet = (set, list) => set.size === list.length && list.every((x) => set.has(x));

  // ===========================================================================
  // Géométrie
  // ===========================================================================
  /** Le rectangle (x, y, w, h) entre deux points, quel que soit le sens du geste. */
  Selection.rect = (a, b) => ({ x: Math.min(a.x, b.x), y: Math.min(a.y, b.y), w: Math.abs(a.x - b.x), h: Math.abs(a.y - b.y) });
  const intersects = (r, b) => b.x < r.x + r.w && b.x + b.w > r.x && b.y < r.y + r.h && b.y + b.h > r.y;
  const contains = (r, b) => b.x >= r.x && b.y >= r.y && b.x + b.w <= r.x + r.w && b.y + b.h <= r.y + r.h;
  /**
   * Les pierres qu'un rectangle de sélection attrape.
   * @param {Record<string,{x,y,w,h}>} boxes  les boîtes des pierres (coordonnées du monde)
   * @param {{x,y,w,h}} rect
   * @param {'touch'|'contain'} [mode='touch']  touch : il suffit d'effleurer ; contain : la pierre entière
   * @returns {string[]}
   */
  Selection.hits = (boxes, rect, mode = 'touch') => {
    const test = mode === 'contain' ? contains : intersects;
    return Object.entries(boxes).filter(([, b]) => b && test(rect, b)).map(([id]) => id);
  };

  // ===========================================================================
  // Pierres d'un espace de travail
  // ===========================================================================
  /**
   * Les racines d'une sélection : les pierres dont le parent direct n'est pas sélectionné (dans l'ordre de la
   * sélection). Une pierre dont le parent est sélectionné voyage avec lui ; une pierre séparée de sa tête par
   * une pierre non sélectionnée devient une racine à son tour.
   */
  Selection.roots = (ws, ids) => {
    const set = new Set(ids);
    return ids.filter((id) => { const n = ws.get(id); return n && !(n.parent && set.has(n.parent.id)); });
  };

  /** Coupe dans un JSON de pierre les suites qui ne sont pas sélectionnées (les adjacentes restent : elles font partie de la pierre). */
  const prune = (j, set) => {
    if (j.next) {
      j.next = j.next.filter((l) => set.has(l.domino.id));
      j.next.forEach((l) => prune(l.domino, set));
      if (!j.next.length) delete j.next;
    }
    for (const side of ['top', 'bottom']) if (j[side]) j[side].forEach((a) => prune(a.domino, set));
    return j;
  };
  /**
   * Le presse-papiers de plusieurs pierres : chaque racine avec ce qui la suit dans la sélection.
   * Les connexions entre pierres sélectionnées sont gardées ; les fils, non. `boxes` (facultatif) : la place
   * de chaque pierre à l'écran, pour qu'une pierre détachée de sa chaîne se recolle au même endroit.
   * @returns {{ format: string, version: 1, dominos: object[] }}
   */
  Selection.toClip = (ws, ids, boxes = {}) => {
    const set = new Set(ids);
    const dominos = Selection.roots(ws, ids).map((id) => {
      const n = ws.get(id);
      const j = prune(D.Serializer.nodeToJSON(ws, n, { next: true }), set);
      if (!j.position && boxes[id]) j.position = { x: boxes[id].x, y: boxes[id].y };
      return j;
    });
    // Les fils dont les deux bouts voyagent dans le presse-papiers (adjacentes comprises).
    const inside = new Set();
    const walk = (j) => { inside.add(j.id); for (const k of ['top', 'bottom', 'next']) (j[k] || []).forEach((a) => walk(a.domino)); };
    dominos.forEach(walk);
    const wires = [...ws.wires.values()].filter((w) => inside.has(w.from.id) && inside.has(w.to.id)).map((w) => D.compact({
      id: w.id, from: { domino: w.from.id, pip: w.from.pip }, to: { domino: w.to.id, pip: w.to.pip },
      blocking: w.blocking === false ? false : undefined, label: w.label, enabled: w.enabled === false ? false : undefined,
      type: w.type || undefined, fields: w.fields && Object.keys(w.fields).length ? D.clone(w.fields) : undefined,
    }));
    return D.compact({ format: CLIP_FORMAT, version: 1, dominos, wires: wires.length ? wires : undefined });
  };
  /** Vrai pour un presse-papiers de plusieurs pierres (sinon c'est le JSON d'une seule). */
  Selection.isClip = (x) => !!(x && x.format === CLIP_FORMAT && Array.isArray(x.dominos));
  /**
   * Colle un presse-papiers dans une partie, avec de nouveaux identifiants. Les pierres libres gardent leur
   * disposition relative, décalée en `at` (le coin haut-gauche du groupe).
   * @returns {Array} les racines créées
   */
  Selection.fromClip = (ws, clip, partie, at) => {
    const list = Selection.isClip(clip) ? clip.dominos : [clip];
    const pos = list.map((j) => j.position).filter(Boolean);
    const x0 = pos.length ? Math.min(...pos.map((p) => p.x)) : 0, y0 = pos.length ? Math.min(...pos.map((p) => p.y)) : 0;
    let row = 0;
    // Comme au chargement d'un projet : les pierres, puis les fils (ils changent certaines faces), puis les collages.
    const report = { warnings: [], errors: [], ids: {} }, links = [];
    const roots = list.map((j) => {
      const node = D.Serializer.loadNode(ws, D.clone(j), partie, { freshIds: true, report, defer: links });
      node.position = j.position ? { x: at.x + j.position.x - x0, y: at.y + j.position.y - y0 } : { x: at.x, y: at.y + (row++) * 160 };
      return node;
    });
    for (const w of (Selection.isClip(clip) && clip.wires) || []) D.Serializer.loadWire(ws, { ...w, id: undefined }, { report, ids: report.ids });
    for (const l of links) D.Serializer._linkLoaded(ws, l, report);
    report.warnings.forEach((m) => ws.log('warn', m));
    return roots;
  };

  D.Selection = Selection;
})(typeof globalThis !== 'undefined' ? globalThis : window);
