      if (n.locked) m.push(`<g class="dk-mark lock" transform="${at(i++)}"><circle r="6.5"/><path d="M-2.6 -0.4h5.2v3.6h-5.2zM-1.6 -0.4v-1.6a1.6 1.6 0 0 1 3.2 0v1.6" fill="none" stroke="currentColor" stroke-width="1.1"/><title>Verrouillée</title></g>`);
