        const more = p.collapsed ? `<g data-id="${p.id}" class="dk-moreg"><rect class="dk-more-bg" x="${r.x + r.w - 9}" y="${r.y - 7}" width="18" height="12" rx="6"/><text class="dk-more" x="${r.x + r.w}" y="${r.y + 1.5}" text-anchor="middle">+${p.collapsed}</text></g>` : '';
