        this._g = { mode: 'pinch', d0: Math.hypot(a.x - b.x, a.y - b.y) || 1, k0: this.view.k, mx: (a.x + b.x) / 2, my: (a.y + b.y) / 2, vx: this.view.x, vy: this.view.y };
