      if (jumpEl) { e.preventDefault(); this.select(jumpEl.dataset.jump); return; }
      // Un point d'abord (même sous l'extrémité d'un fil) : tirer un fil, ou reprendre celui qui y arrive.
      const stack = typeof document.elementsFromPoint === 'function' ? document.elementsFromPoint(e.clientX, e.clientY) : [e.target];
      const pipEl = stack.find((x) => x.classList && x.classList.contains('t-pip-hit'));
