      g.moved = true;
      const m = this.marquee, box = D.Selection.rect({ x: g.x0, y: g.y0 }, { x, y });
      m.setAttribute('x', box.x); m.setAttribute('y', box.y); m.setAttribute('width', box.w); m.setAttribute('height', box.h);
      m.removeAttribute('hidden');
