      const hits = D.Selection.hits(g.boxes, D.Selection.rect(g.w0, this.toWorld(e.clientX, e.clientY)));
      g.hits = hits;
      this.selection.set([...g.base, ...hits.filter((id) => !g.base.includes(id))]);
