      this.selectMany(ids, { primary: (g.hits && g.hits[g.hits.length - 1]) || this.selection.primary, focus: true });
      this._say(ids.length ? `${D.plural(ids.length, 'pierre')} sélectionnée${ids.length > 1 ? 's' : ''}.` : 'Aucune pierre sélectionnée.');
