      const g = this._g;
      this._g = null;
      this.svg.classList.remove('panning', 'wiring');
      if (!g) return;
      if (g.mode === 'pan' && !g.moved && !cancel) { this.select(null, { focus: false }); this.svg.focus({ preventScroll: true }); }
