  // ---------------------------------------------------------------------------
  // Utilitaires de dessin
  // ---------------------------------------------------------------------------
  function curvy(a, r = 10) {
    return a.map((p, i) => {
      if (!i) return `M${p[0].toFixed(1)} ${p[1].toFixed(1)}`;
      if (i === a.length - 1) return `L${p[0].toFixed(1)} ${p[1].toFixed(1)}`;
      const [px, py] = a[i - 1], [nx, ny] = a[i + 1];
      const k1 = Math.min(r, Math.hypot(p[0] - px, p[1] - py) / 2), k2 = Math.min(r, Math.hypot(nx - p[0], ny - p[1]) / 2);
      const u = (q, k) => { const L0 = Math.hypot(q[0] - p[0], q[1] - p[1]) || 1; return [p[0] + (q[0] - p[0]) / L0 * k, p[1] + (q[1] - p[1]) / L0 * k]; };
      const b1 = u([px, py], k1), b2 = u([nx, ny], k2);
      return `L${b1[0].toFixed(1)} ${b1[1].toFixed(1)} Q${p[0].toFixed(1)} ${p[1].toFixed(1)} ${b2[0].toFixed(1)} ${b2[1].toFixed(1)}`;
    }).join(' ');
  }
