      const half = (side) => {
        const [cx, cy] = this.faceC(0, 0, h, side);
        return isV(h) ? { x: 0, y: cy - T / 2, w: T, h: T } : { x: cx - T / 2, y: 0, w: T, h: T };
      };
      const hin = half('in'), hout = half('out');
      const place = o.adjacents === 'list' ? (items, PR, side, fam) => list(items, PR, side, fam, 0, n.id) : (items, PR, side, fam) => family(items, PR, side, fam, 0, T, [], n.id);
      place(n.top, { ...P, ...(isV(h) ? { y: hin.y, h: T } : { x: hin.x, w: T }) }, sideTop, 'top');
