      // GRID : une grille spatiale des boîtes occupées (pour trouver un obstacle sans balayer toute la table).
      const reset = () => { R = {}; adj = []; links = []; joints = []; occ = []; edges = []; notes = {}; jams = []; ORD = []; GRID = new Map(); };
      const mark = () => ({ k: ORD.length, a: adj.length, l: links.length, j: joints.length, o: occ.length, e: edges.length, jm: jams.length });
      const rollback = (m) => {
        for (let i = ORD.length - 1; i >= m.k; i--) { delete R[ORD[i]]; delete notes[ORD[i]]; }
        ORD.length = m.k;
        adj.length = m.a; links.length = m.l; joints.length = m.j; occ.length = m.o; edges.length = m.e; jams.length = m.jm;
      };
