      const cells = (b, f) => { for (let gx = Math.floor(b.x1 / CELL); gx <= Math.floor(b.x2 / CELL); gx++) for (let gy = Math.floor(b.y1 / CELL); gy <= Math.floor(b.y2 / CELL); gy++) f(`${gx}:${gy}`); };
      const occAdd = (q) => { Object.defineProperty(q, '_i', { value: occ.length, writable: true }); occ.push(q); cells(q, (k) => { let c = GRID.get(k); if (!c) GRID.set(k, (c = [])); c.push(q); }); };
